import { useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { isWon } from '../game.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { useGame } from '../session/use-game.ts';
import { GameStatus } from '../status/GameStatus.tsx';
import { Bracket } from './Bracket.tsx';
import { decodeTournament, encodeTournament } from './format.ts';
import {
  createTournament,
  currentMatch,
  currentPlayer,
  nextMatch,
  normalizeNames,
  recordResult,
  roundName,
  roundSize,
} from './rules.ts';
import type { Tournament as TournamentData } from './rules.ts';
import { readHistory, saveHistory } from './storage.ts';
import './tournament.css';

function deals(size: number, count: number, used: string[]): string[] {
  const codes = [...used];
  for (let i = 0; i < count; i++) {
    let code: string;
    do {
      code = freshBoardCode(size);
    } while (codes.includes(code));
    codes.push(code);
  }
  return codes.slice(used.length);
}
export function Tournament({ back }: { back(): void }) {
  const game = useGame(true);
  const board = useRef<BoardFocus>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const keep = useRef<HTMLButtonElement>(null);
  const pending = useRef<(() => void) | null>(null);
  const [count, setCount] = useState(4);
  const [names, setNames] = useState(Array<string>(8).fill(''));
  const [event, setEvent] = useState<TournamentData | null>(null);
  const [history, setHistory] = useState(readHistory);
  const [draft, setDraft] = useState('');
  const [notice, setNotice] = useState('');
  const [announcement, setAnnouncement] = useState(0);
  function announce(message: string) {
    setNotice(message);
    setAnnouncement((n) => n + 1);
  }
  useEffect(() => {
    heading.current?.focus();
  }, []);
  useEffect(() => {
    if (event?.phase !== 'playing' || !isWon(game.session.game)) return;
    const finished = recordResult(event, {
      moves: game.session.game.moves,
      elapsedMs: game.session.game.elapsedMs,
    });
    setEvent(finished);
    if (finished.phase === 'complete') {
      setHistory((old) => {
        const items = [finished, ...old.items].slice(0, 10);
        return { items, blocked: !saveHistory(items) };
      });
      announce(`Champion: ${finished.names[currentMatch(finished).winner!]}`);
    } else
      announce(
        finished.phase === 'turn'
          ? `Now playing: ${finished.names[currentPlayer(finished)]}`
          : `Winner: ${
              finished.names[
                finished.rounds
                  .at(-1)!
                  .filter((m) => m.winner !== null)
                  .at(-1)!.winner!
              ]
            }`,
      );
  }, [event, game.session.game]);
  function confirm(action: () => void) {
    if (!event || event.phase === 'complete') {
      action();
      return;
    }
    pending.current = action;
    dialog.current?.showModal();
    keep.current?.focus();
  }
  function start() {
    const result = normalizeNames(names.slice(0, count));
    if (result.error) {
      announce(result.error);
      return;
    }
    setEvent(createTournament(result.names, deals(roundSize(count / 2), count / 2, [])));
    announce(`Now playing: ${result.names[0]}`);
  }
  function startTurn() {
    if (!event) return;
    setNotice('');
    game.startDeal(currentMatch(event).code);
    setEvent({ ...event, phase: 'playing' });
  }
  function advance() {
    if (!event) return;
    if (event.phase === 'turn') {
      const next = { ...event, phase: 'ready' as const };
      setEvent(next);
      announce(`Now playing: ${next.names[currentPlayer(next)]}`);
      return;
    }
    const last = event.rounds.at(-1)!;
    const used = event.rounds.flatMap((r) => r.map((m) => m.code));
    const next = nextMatch(
      event,
      last.every((m) => m.winner !== null)
        ? deals(roundSize(last.length / 2), last.length / 2, used)
        : [],
    );
    setEvent(next);
    announce(`Now playing: ${next.names[currentPlayer(next)]}`);
  }
  function exportEvent() {
    if (!event) {
      announce('Start or load a tournament to export it.');
      return;
    }
    setDraft(
      encodeTournament(
        event.phase === 'playing' ? { ...event, snapshot: game.exportSnapshot() } : event,
      ),
    );
    announce('Tournament exported.');
  }
  function load() {
    const result = decodeTournament(draft);
    if (!result.tournament) {
      announce(result.error);
      return;
    }
    const loaded = result.tournament;
    confirm(() => {
      if (loaded.phase === 'playing' && loaded.snapshot) game.loadSnapshot(loaded.snapshot);
      setEvent(loaded);
      announce('Tournament loaded.');
    });
  }
  const match = event && currentMatch(event);
  return (
    <section className="tournament">
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      {!event && (
        <>
          <div className="tournament-form">
            <label htmlFor="players">Players</label>
            <select
              id="players"
              className="control"
              value={count}
              onChange={(e) => setCount(Number(e.target.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
            {names.slice(0, count).map((name, i) => (
              <label key={i}>
                Player {i + 1}
                <input
                  className="control"
                  value={name}
                  onChange={(e) =>
                    setNames((old) => old.map((n, j) => (i === j ? e.target.value : n)))
                  }
                />
              </label>
            ))}
            <button className="control" onClick={start}>
              Start tournament
            </button>
          </div>
          <h3>Past tournaments</h3>
          {history.blocked && <p>Progress won't be saved on this device.</p>}
          {history.items.length === 0 ? (
            <p>No past tournaments.</p>
          ) : (
            <ul>
              {history.items.map((past, i) => (
                <li key={i}>
                  <button
                    className="control"
                    onClick={() => {
                      setEvent(past);
                      announce('Tournament loaded.');
                    }}
                  >
                    Champion: {past.names[currentMatch(past).winner!]}
                  </button>
                </li>
              ))}
            </ul>
          )}
          <button className="control" onClick={back}>
            Back to game
          </button>
        </>
      )}
      {event && match && (
        <>
          <p>Round: {roundName(event.rounds.at(-1)!.length)}</p>
          {event.phase === 'complete' ? (
            <>
              <p>Champion: {event.names[match.winner!]}</p>
              <button className="control" onClick={back}>
                Back to game
              </button>
            </>
          ) : (
            <>
              <p>Now playing: {event.names[currentPlayer(event)]}</p>
              {event.phase === 'ready' && (
                <button className="control" onClick={startTurn}>
                  Start turn
                </button>
              )}
              {event.phase === 'playing' && game.session.paused && (
                <button className="control" onClick={game.resume}>
                  Resume
                </button>
              )}
              {event.phase === 'turn' && (
                <button className="control" onClick={advance}>
                  Next turn
                </button>
              )}
              {event.phase === 'match' && (
                <button className="control" onClick={advance}>
                  Next match
                </button>
              )}
              <button className="control" onClick={() => confirm(back)}>
                Leave tournament
              </button>
            </>
          )}
          {event.phase === 'playing' && (
            <>
              <GameStatus
                game={game.session.game}
                best={undefined}
                celebration={game.session.celebration}
              />
              <p id="board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                Space reveals a card.
              </p>
              <Board
                key={game.session.generation}
                game={game.session.game}
                activate={(index) => {
                  setNotice('');
                  game.activate(index);
                }}
                ref={board}
              />
            </>
          )}
          <Bracket tournament={event} />
        </>
      )}
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={`${announcement}-${game.session.announcement}`}>
            {notice || game.session.feedback}
          </span>
        </p>
      </div>
      <div className="tournament-exchange">
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
        />
        <div>
          <button className="control" onClick={exportEvent}>
            Export tournament
          </button>
          <button className="control" onClick={load}>
            Load tournament
          </button>
        </div>
      </div>
      <dialog
        ref={dialog}
        onCancel={() => {
          pending.current = null;
        }}
      >
        <p>Leave this unfinished tournament?</p>
        <button
          ref={keep}
          className="control"
          onClick={() => {
            pending.current = null;
            dialog.current?.close();
          }}
        >
          Keep playing
        </button>
        <button
          className="control"
          onClick={() => {
            dialog.current?.close();
            pending.current?.();
            pending.current = null;
          }}
        >
          Leave
        </button>
      </dialog>
    </section>
  );
}

